from datetime import date

def evidence_problems(case, evidence, today, max_age_days):
    out = []
    def walk(node):
        if 'children' in node:
            for child in node['children']:
                walk(child)
            return
        if not node['evidence']:
            out.append(f"{node['id']}: no evidence")
        for eid in node['evidence']:
            item = evidence[eid]
            if not item['passed']:
                out.append(f"{node['id']}: {eid} failed")
            elif (today - item['date']).days > max_age_days:
                out.append(f"{node['id']}: {eid} stale")
    walk(case)
    return out

